    rel = p.relative_to(root)
    parts = list(rel.with_suffix("").parts)
    if parts[0]=="src": parts=parts[1:]
    if parts[-1]=="__init__": parts=parts[:-1]
    mods[".".join(parts)] = p
def resolve(name):
    while name:
        if name in mods: return name
        name = name.rpartition(".")[0]
edges = collections.defaultdict(set); ext=collections.Counter()
for m,p in mods.items():
    tree = ast.parse(p.read_text())
    pkg = m if p.name=="__init__.py" else m.rpartition(".")[0]
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                r=resolve(a.name); 
                if r: edges[m].add(r)
                else: ext[a.name.split(".")[0]]+=1
        elif isinstance(n, ast.ImportFrom):
            if n.level:
                base = pkg.split(".")
                base = base[:len(base)-(n.level-1)] if n.level>1 else base
                full=".".join(base+([n.module] if n.module else []))
            else: full=n.module
            for a in n.names:
                r = resolve(full+"."+a.name) or resolve(full)
                if r: edges[m].add(r)
                elif not n.level: ext[full.split(".")[0]]+=1
def reach(starts):
